#!/usr/bin/env python3
"""Compute the CSX-122 late-phase rainfall ledger ground truth."""

from __future__ import annotations

import json
import re
from collections import Counter, defaultdict
from html.parser import HTMLParser
from pathlib import Path
from typing import Any


TASK_ID = "CSX-122_Q1"
EVENT_ID = "CSX-122"

EVENT_METADATA = "metadata/event.json"
ANCHOR_REPORT = "data/event_reports/event_reports_001_Locked_package_evidence_report.html"
ANCHOR_LOCK = "data/event_reports/event_reports_004_Locked_event_anchor_Cyclone_Freddy.json"
GDACS_CATALOG = "data/event_catalogs/event_catalogs_001_GDACS_tropical_cyclone_event_API.json"
OPEN_METEO = "data/physical_hazard/physical_hazard_002_Open-Meteo_historical_wind_rain_point_API.json"
GPM = "data/physical_hazard/physical_hazard_006_GPM_IMERG_V07_event_accumulated_precipitation.json"
CHIRPS = "data/physical_hazard/physical_hazard_007_CHIRPS_daily_event_accumulated_precipitation.json"
WORLDPOP = "data/exposure_impact/exposure_impact_004_WorldPop_GP_100m_population_sum.json"
OSM_CONTEXT = (
    "data/exposure_impact/exposure_impact_005_OpenStreetMap_Overpass_bounded_"
    + "A"
    + "OI_slice.json"
)
AREA_BOX = (
    "data/geospatial_context/geospatial_context_003_compact_per-event_"
    + "A"
    + "OI_derived_from_event_bbox.json"
