SOURCE_FILES = [
    EVENT_METADATA,
    ANCHOR_REPORT,
    ANCHOR_LOCK,
    GDACS_CATALOG,
    OPEN_METEO,
    GPM,
    CHIRPS,
    WORLDPOP,
