def package_dir() -> Path:
    return (
        Path(__file__).resolve().parents[3]
        / "event_packages"
        / "standard_event_packages"
        / "packages"
        / EVENT_ID
    )


def read_json(root: Path, rel_path: str, *, strict: bool = True) -> Any:
    text = (root / rel_path).read_text(encoding="utf-8", errors="replace")
    return json.loads(text, strict=strict)


class TextExtractor(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self.parts: list[str] = []

    def handle_data(self, data: str) -> None:
        text = " ".join(data.split())
        if text:
            self.parts.append(text)

    def text(self) -> str:
        return "\n".join(self.parts)


def html_text(path: Path) -> str:
    parser = TextExtractor()
    parser.feed(path.read_text(encoding="utf-8", errors="ignore"))
    return parser.text()


def first_float(pattern: str, text: str) -> float | None:
    match = re.search(pattern, text, flags=re.IGNORECASE)
    if not match:
        return None
    return float(match.group(1).replace(" ", "").replace(",", ""))


def round_number(value: float | int | None, digits: int = 3) -> float | None:
    if value is None:
        return None
    return round(float(value), digits)


def summarize_open_meteo(data: dict[str, Any]) -> dict[str, Any]:
    hourly = data["hourly"]
    daily_precip: defaultdict[str, float] = defaultdict(float)
    max_hourly_precip = {"time": None, "mm": -1.0}
    max_gust = {"time": None, "kmh": -1.0}
    max_wind = {"time": None, "kmh": -1.0}

    for time, precipitation, gust, wind in zip(
        hourly["time"],
        hourly["precipitation"],
        hourly["wind_gusts_10m"],
        hourly["wind_speed_10m"],
    ):
        if precipitation is not None:
            daily_precip[time[:10]] += float(precipitation)
            if float(precipitation) > max_hourly_precip["mm"]:
                max_hourly_precip = {"time": time, "mm": float(precipitation)}
        if gust is not None and float(gust) > max_gust["kmh"]:
            max_gust = {"time": time, "kmh": float(gust)}
        if wind is not None and float(wind) > max_wind["kmh"]:
            max_wind = {"time": time, "kmh": float(wind)}

    peak_day, peak_mm = max(daily_precip.items(), key=lambda item: item[1])
    late_phase_total = sum(
        amount
        for day, amount in daily_precip.items()
        if "2023-03-12" <= day <= "2023-03-15"
    )

    return {
        "point_latitude": data["latitude"],
        "point_longitude": data["longitude"],
        "elevation_m": data["elevation"],
        "hourly_count": len(hourly["time"]),
        "start_time": hourly["time"][0],
        "end_time": hourly["time"][-1],
        "total_precip_mm": round_number(sum(daily_precip.values()), 3),
        "peak_daily_precip_date": peak_day,
        "peak_daily_precip_mm": round_number(peak_mm, 3),
        "late_phase_precip_mm_2023_03_12_to_15": round_number(late_phase_total, 3),
        "max_hourly_precip_time": max_hourly_precip["time"],
        "max_hourly_precip_mm": round_number(max_hourly_precip["mm"], 3),
        "max_wind_speed_time": max_wind["time"],
        "max_wind_speed_kmh": round_number(max_wind["kmh"], 3),
        "max_wind_gust_time": max_gust["time"],
        "max_wind_gust_kmh": round_number(max_gust["kmh"], 3),
    }


def gdacs_features(data: dict[str, Any]) -> dict[str, Any]:
    cyclone = None
    flood = None
    for feature in data.get("features", []):
        props = feature.get("properties", {})
        if props.get("eventtype") == "TC" and props.get("eventname") == "FREDDY-23":
            cyclone = props
        if props.get("eventtype") == "FL" and props.get("country") == "Malawi":
            flood = props
    if not cyclone or not flood:
        raise ValueError("Expected Freddy tropical-cyclone and Malawi flood catalog features")
    return {
        "tc": {
            "eventid": cyclone["eventid"],
            "episodeid": cyclone["episodeid"],
            "name": cyclone["name"],
            "alertlevel": cyclone["alertlevel"],
            "country": cyclone["country"],
            "fromdate": cyclone["fromdate"],
            "todate": cyclone["todate"],
            "severity_kmh": cyclone["severitydata"]["severity"],
        },
        "flood": {
            "eventid": flood["eventid"],
            "episodeid": flood["episodeid"],
            "name": flood["name"],
            "alertlevel": flood["alertlevel"],
            "country": flood["country"],
            "fromdate": flood["fromdate"],
            "todate": flood["todate"],
        },
    }


def summarize_area_box(data: dict[str, Any]) -> dict[str, Any]:
    ring = data["geometry"]["coordinates"][0]
    lon_values = [coord[0] for coord in ring]
    lat_values = [coord[1] for coord in ring]
    return {
        "type": data["geometry"]["type"],
        "min_lon": min(lon_values),
        "max_lon": max(lon_values),
        "min_lat": min(lat_values),
        "max_lat": max(lat_values),
    }


def summarize_osm(data: dict[str, Any]) -> dict[str, Any]:
    elements = data.get("elements", [])
    element_types: Counter[str] = Counter()
    amenities: Counter[str] = Counter()
    highways: Counter[str] = Counter()
    for element in elements:
        element_types[element.get("type", "unknown")] += 1
        tags = element.get("tags") or {}
        if "amenity" in tags:
            amenities[tags["amenity"]] += 1
        if "highway" in tags:
            highways[tags["highway"]] += 1
    return {
        "element_count": len(elements),
        "element_types": dict(sorted(element_types.items())),
        "top_amenities": dict(amenities.most_common(5)),
        "top_highways": dict(highways.most_common(5)),
    }


def main() -> None:
    root = package_dir()
    metadata = read_json(root, EVENT_METADATA)
    anchor_lock = read_json(root, ANCHOR_LOCK)
    report_text = html_text(root / ANCHOR_REPORT)
    gdacs = gdacs_features(read_json(root, GDACS_CATALOG))
    open_meteo = summarize_open_meteo(read_json(root, OPEN_METEO))
    gpm = read_json(root, GPM)
    chirps = read_json(root, CHIRPS)
    worldpop = read_json(root, WORLDPOP)
    osm = summarize_osm(read_json(root, OSM_CONTEXT, strict=False))
    s1 = read_json(root, S1)
    alpha = read_json(root, ALPHA_CHANGE)

    wmo_duration_days = first_float(r"duration of\s+([0-9.]+)\s+days", report_text)
    wmo_distance_km = first_float(r"travelled\s+([0-9 ]+)\s+km", report_text)

    gpm_mean = round_number(gpm["stats"]["gpm_event_precip_mm_mean"], 3)
    chirps_mean = round_number(chirps["stats"]["chirps_event_precip_mm_mean"], 3)
    gpm_max = round_number(gpm["stats"]["gpm_event_precip_mm_max"], 3)
    chirps_max = round_number(chirps["stats"]["chirps_event_precip_mm_max"], 3)
    paired_gridded_mean = round_number((gpm_mean + chirps_mean) / 2, 3)

    numeric_anchors = {
        "event_total_point_rain_mm": open_meteo["total_precip_mm"],
        "late_phase_point_rain_mm": open_meteo[
            "late_phase_precip_mm_2023_03_12_to_15"
        ],
        "gridded_rainfall_mean_mm": paired_gridded_mean,
        "exposed_population_context": round_number(
            worldpop["population_sum"]["population"], 3
        ),
    }

    derived_tests = {
        "late_phase_share_of_event_point_rain": round_number(
            numeric_anchors["late_phase_point_rain_mm"]
            / numeric_anchors["event_total_point_rain_mm"],
            3,
        ),
        "gridded_mean_to_late_point_rain_ratio": round_number(
            numeric_anchors["gridded_rainfall_mean_mm"]
            / numeric_anchors["late_phase_point_rain_mm"],
            3,
        ),
    }

    numeric_tolerances = {
        "event_total_point_rain_mm": {
            "expected": numeric_anchors["event_total_point_rain_mm"],
            "absolute_tolerance": 0.5,
            "units": "mm",
        },
        "late_phase_point_rain_mm": {
